CREATE EXTENSION postgis;
SELECT postgis_full_version();
SET CLIENT_ENCODING TO UTF8;
SET STANDARD_CONFORMING_STRINGS TO ON;
BEGIN;
CREATE TABLE "public"."barrios" (gid serial,
"barrio" varchar(254),
"localidad" varchar(75),
"area_has" numeric,
"area_m2" numeric,
"area_km2" numeric);
ALTER TABLE "public"."barrios" ADD PRIMARY KEY (gid);
SELECT AddGeometryColumn('public','barrios','geom','4326','MULTIPOLYGON',4);
COMMIT;
ANALYZE "public"."barrios";
